#!/usr/bin/env python3
# Not team code (generated by Claude, 13 Nov 2026, at Swarneel's request).
# Builds the Stairway A/B material from the song in test_audio/stairway_source.mp3:
#   1. master clip: START_S..START_S+LEN_S, 48 kHz mono, from the song's own decode (10 ms fades)
#   2. plain 32k:   the clip encoded to 32 kbit/s (the board's source material)
#   3. reference:   the clip encoded to 128 kbit/s (quality ceiling, NOT a lossless master: the
#                   song file is itself 128 kbit/s, so this is a second lossy pass)
#   4. enhanced:    plain 32k decode + original enhancement (fc 7.2 kHz, gain 1, SW5/SW6 down)
# Then reports full-band and above-fc distance to the reference, for the quality judgement.
#
# Usage: python3 model/goal2/make_stairway_ab.py [START_S] [LEN_S]
import os
import subprocess
import sys

import numpy as np
from scipy.io import wavfile

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import ref  # noqa: E402  original float chain, unchanged

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
OUT = os.path.join(ROOT, "test_audio", "stairway")
SRC = os.path.join(ROOT, "test_audio", "stairway_source.mp3")
FS = 48000
FC = 7200
START_S = float(sys.argv[1]) if len(sys.argv) > 1 else 120.0
LEN_S = float(sys.argv[2]) if len(sys.argv) > 2 else 20.0
TAG = f"s{int(START_S)}_{int(LEN_S)}s"


def ff(*args):
    subprocess.run(["ffmpeg", "-v", "error", "-y", *args], check=True)


def lsd(y, r, f_min):
    from scipy.signal import stft
    n = min(len(y), len(r))
    _, _, Y = stft(y[:n], fs=FS, nperseg=1024, noverlap=512)
    _, _, R = stft(r[:n], fs=FS, nperseg=1024, noverlap=512)
    f = np.fft.rfftfreq(1024, 1 / FS)
    k = f >= f_min
    d = 10 * np.log10(np.abs(Y[k]) ** 2 + 1e-9) - 10 * np.log10(np.abs(R[k]) ** 2 + 1e-9)
    return float(np.sqrt(np.mean(d ** 2)))


def main():
    os.makedirs(OUT, exist_ok=True)
    master = os.path.join(OUT, f"master_{TAG}_48k_mono.wav")
    ff("-ss", str(START_S), "-t", str(LEN_S), "-i", SRC, "-ac", "1", "-ar", str(FS),
       "-af", "afade=t=in:d=0.01,afade=t=out:st=%f:d=0.01" % (LEN_S - 0.01),
       "-c:a", "pcm_s16le", master)
    _, m16 = wavfile.read(master)
    m = m16.astype(float)

    p32 = os.path.join(OUT, f"plain_32k_{TAG}.mp3")
    r128 = os.path.join(OUT, f"reference_128k_{TAG}.mp3")
    ff("-i", master, "-c:a", "libmp3lame", "-b:a", "32k", p32)
    ff("-i", master, "-c:a", "libmp3lame", "-b:a", "128k", r128)

    def decode(p):
        out = subprocess.run(["ffmpeg", "-v", "error", "-i", p, "-ac", "1", "-ar", str(FS),
                              "-f", "s16le", "-"], capture_output=True, check=True).stdout
        return np.frombuffer(out, dtype="<i2").astype(float)

    plain = decode(p32)
    ref128 = decode(r128)
    enh = ref.enhance(plain, FC, 1)
    enh16 = np.clip(np.round(enh), -32768, 32767).astype("<i2")
    enh_path = os.path.join(OUT, f"enhanced_32k_{TAG}.wav")
    wavfile.write(enh_path, FS, enh16)
    wavfile.write(os.path.join(OUT, f"plain_32k_{TAG}.wav"), FS,
                  np.clip(np.round(plain), -32768, 32767).astype("<i2"))

    print(f"clip {START_S:.0f}-{START_S + LEN_S:.0f} s of the song, {LEN_S:.1f} s, {len(plain)} samples")
    print(f"clipped samples in enhanced: {int(np.sum(np.abs(enh) > 32767))}")
    print(f"{'variant':<34}{'LSD full band':>15}{'LSD above fc':>15}")
    for name, y in [("plain 32k", plain), ("enhanced 32k (original)", enh)]:
        print(f"{name:<34}{lsd(y, ref128, 0):>15.2f}{lsd(y, ref128, FC):>15.2f}")
    print("files:")
    for p in (master, p32, r128, enh_path):
        print("  ", p)


if __name__ == "__main__":
    main()
